CREATE TABLE [dbo].[ccloglogin](	  [User_id] SMALLINT NOT NULL	, [Extension] VARCHAR(7) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [TipoMov] TINYINT NOT NULL	, [fecha] DATETIME NOT NULL DEFAULT(getdate()))CREATE NONCLUSTERED INDEX [IX_ccLogLogin] ON [dbo].[ccloglogin] ([User_id] ASC)CREATE NONCLUSTERED INDEX [IX_ccLogLogin_1] ON [dbo].[ccloglogin] ([TipoMov] ASC)CREATE NONCLUSTERED INDEX [IX_ccLogLogin_2] ON [dbo].[ccloglogin] ([fecha] ASC)CREATE NONCLUSTERED INDEX [IX_ccLogLogin_3] ON [dbo].[ccloglogin] ([User_id] ASC, [TipoMov] ASC, [fecha] ASC)CREATE NONCLUSTERED INDEX [IX_ccLogLogin_4] ON [dbo].[ccloglogin] ([User_id] ASC, [fecha] ASC)CREATE NONCLUSTERED INDEX [IX_ccLogLogin_5] ON [dbo].[ccloglogin] ([TipoMov] ASC, [fecha] ASC)